import{_ as e,o as a,c as d,a3 as s}from"./chunks/framework.DeRSg1wr.js";const _=JSON.parse('{"title":"日志标签模板自定义","description":"TLog 2.0 标签模板的六个占位符、默认值和 MDC 对应关系。","frontmatter":{"title":"日志标签模板自定义","date":"2022-09-12T13:46:57.000Z","permalink":"/pages/239d32/","description":"TLog 2.0 标签模板的六个占位符、默认值和 MDC 对应关系。"},"headers":[],"relativePath":"pages/239d32/index.md","filePath":"10.文档/080.日志标签模板自定义.md"}'),p={name:"pages/239d32/index.md"};function o(i,t,r,c,n,l){return a(),d("div",null,[...t[0]||(t[0]=[s(`<h1 id="日志标签模板自定义" tabindex="-1">日志标签模板自定义 <a class="header-anchor" href="#日志标签模板自定义" aria-label="Permalink to &quot;日志标签模板自定义&quot;">​</a></h1><p>默认完整标签为 <code>&lt;$spanId&gt;&lt;$traceId&gt;</code>。可以在 Spring Boot 配置中调整格式：</p><div class="language-yaml vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang">yaml</span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span style="--shiki-light:#22863A;--shiki-dark:#85E89D;">tlog</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">:</span></span>
<span class="line"><span style="--shiki-light:#22863A;--shiki-dark:#85E89D;">  pattern</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">: </span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;">&#39;[$preApp][$preIp][$spanId][$traceId]&#39;</span></span></code></pre></div><table tabindex="0"><thead><tr><th>占位符</th><th>含义</th></tr></thead><tbody><tr><td><code>$preApp</code></td><td>上游应用名称</td></tr><tr><td><code>$preHost</code></td><td>上游主机名</td></tr><tr><td><code>$preIp</code></td><td>上游 IP</td></tr><tr><td><code>$currIp</code></td><td>当前节点 IP</td></tr><tr><td><code>$spanId</code></td><td>当前节点的层级 spanId</td></tr><tr><td><code>$traceId</code></td><td>当前请求的 traceId</td></tr></tbody></table><p>例如上游为 <code>order-service</code>，当前 span 为 <code>0.1</code>，可得到：</p><div class="language-text vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang">text</span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span>[order-service][10.0.0.8][0.1][demo-request-001]</span></span></code></pre></div><p>缺失或空白的字段显示为 <code>NONE</code>；空白模板通过配置初始化时保留默认模板。模板不会改变传播头名称或 spanId 的生成规则。</p><p>采用 MDC 时，<code>%X{tl}</code> 读取这份完整标签；<code>%X{tlogTraceId}</code> 等独立字段不会因为模板变化而改名。纯 Java 应用可在开始处理请求前调用 <code>TLogLabelGenerator.setLabelPattern(...)</code>，该设置是进程级配置，不应按请求切换。</p><p>业务参数标签使用另一个方法级配置 <code>@TLogAspect(pattern = &quot;[{}]&quot;)</code>，与这里的全局模板不同，见<a href="/pages/9c287d/">业务标签</a>。</p>`,9)])])}const g=e(p,[["render",o]]);export{_ as __pageData,g as default};
